import { readFileSync } from 'node:fs';

import { describe, expect, it } from 'vitest';

import { CsvError, readCsvDicts, readCsvRows } from './csv-reader';

type CsvCase = [
  string,
  string[][] | string,
  Record<string, string | string[] | null>[] | string,
];

// Generated by tools/fixtures/generate_csv_cases.py with Python's csv.
const CASES = JSON.parse(
  readFileSync(
    new URL('__fixtures__/csv-reader.json', import.meta.url),
    'utf8',
  ),
) as CsvCase[];

function outcome<T>(read: () => T): T | string {
  try {
    return read();
  } catch (error) {
    return `ERR ${(error as Error).message}`;
  }
}

describe('readCsvRows matches Python csv.reader', () => {
  // Expected values from Python 3.14: list(csv.reader(io.StringIO(text)))
  const cases: [string, string[][]][] = [
    [
      'a,b,c\n1,2,3\n',
      [
        ['a', 'b', 'c'],
        ['1', '2', '3'],
      ],
    ],
    ['a,b\n\n1,2\n', [['a', 'b'], [], ['1', '2']]],
    [
      'a,b\r\n1,2\r\n',
      [
        ['a', 'b'],
        ['1', '2'],
      ],
    ],
    ['a,"b,c",d\n', [['a', 'b,c', 'd']]],
    ['"a ""q"" b",c\n', [['a "q" b', 'c']]],
    ['"ab"cd,e\n', [['abcd', 'e']]],
    ['a"b,c\n', [['a"b', 'c']]],
    ['a,b,\n', [['a', 'b', '']]],
    ['a,b,', [['a', 'b', '']]],
    ['"unterminated\nmore', [['unterminated\nmore']]],
    ['"multi\nline",x\n', [['multi\nline', 'x']]],
    [',,\n', [['', '', '']]],
    ['x', [['x']]],
  ];

  it.each(cases)('%j', (text, expected) => {
    expect(readCsvRows(text)).toEqual(expected);
  });
});

describe('readCsvDicts matches Python csv.DictReader', () => {
  it('pads short rows with null, keeps extra fields under null and skips blank rows', () => {
    const rows = [...readCsvDicts('a,b\n1\n\n1,2,3\n')];
    expect(rows).toEqual([
      new Map([
        ['a', '1'],
        ['b', null],
      ]),
      new Map<string | null, string | string[] | null>([
        ['a', '1'],
        ['b', '2'],
        [null, ['3']],
      ]),
    ]);
  });

  it('empty input has no rows', () => {
    expect([...readCsvDicts('')]).toEqual([]);
  });

  it('takes a blank first row as an empty header, like Python', () => {
    expect([...readCsvDicts('\nx,y\n')]).toEqual([
      new Map([[null, ['x', 'y']]]),
    ]);
  });
});

describe('differential corpus against Python csv', () => {
  it(`matches csv.reader and csv.DictReader on ${CASES.length} texts`, () => {
    const mismatches = CASES.filter(([text, rows, dicts]) => {
      const mineRows = outcome(() => readCsvRows(text));
      const mineDicts = outcome(() =>
        [...readCsvDicts(text)].map(row =>
          Object.fromEntries(
            [...row].map(([key, value]) => [key ?? '__None__', value]),
          ),
        ),
      );
      return (
        JSON.stringify(mineRows) !== JSON.stringify(rows) ||
        JSON.stringify(mineDicts) !== JSON.stringify(dicts)
      );
    });
    expect(mismatches).toEqual([]);
  });

  it('enforces the default field size limit', () => {
    expect(readCsvRows('a'.repeat(131_072))[0]?.[0]?.length).toBe(131_072);
    expect(() => readCsvRows('a'.repeat(131_073))).toThrow(
      new CsvError('field larger than field limit (131072)'),
    );
  });
});
